const supersedeQueued = `-- name: SupersedeQueued :many
UPDATE deployments
SET status = 'cancelled', cancelled_at = now(), failure_reason = $1
WHERE app_id = $2 AND number < $3 AND status = 'queued'
RETURNING id, number
`

type SupersedeQueuedParams struct {
	Reason string
	AppID  uuid.UUID
	Number int32
}

type SupersedeQueuedRow struct {
	ID     uuid.UUID
	Number int32
}

// A newer deploy replaces older ones still waiting in the queue.
func (q *Queries) SupersedeQueued(ctx context.Context, arg SupersedeQueuedParams) ([]SupersedeQueuedRow, error) {
	rows, err := q.db.Query(ctx, supersedeQueued, arg.Reason, arg.AppID, arg.Number)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SupersedeQueuedRow{}
	for rows.Next() {
		var i SupersedeQueuedRow
		if err := rows.Scan(&i.ID, &i.Number); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

